#!/usr/bin/env node
/**
 * Tests for the deliver flow wording: questions up front, the build launch, real tests only after asking,
 * the Verification table, the skill caps, and a clean kit validation.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (rel) => readFileSync(join(ROOT, rel), 'utf8');
const skill = () => read('skills/deliver/SKILL.md');

test('given deliver SKILL.md, when read, then every closed question is asked up front in one round', () => {
  // Given
  const text = skill();

  // When
  const line = text.split('\n').find((l) => /ask them in \*\*one\*\* AskUserQuestion round/.test(l));

  // Then
  assert.ok(line, 'no line asks the questions in one round');
  assert.match(text, /### 2\. Questions — once, up front/);
});

test('given deliver SKILL.md, when read, then M and L launch the build workflow with its args', () => {
  // Given
  const text = skill();

  // When
  const line = text.split('\n').find((l) => l.includes('`Workflow` tool with `name: build`'));

  // Then
  assert.ok(line, 'no line launches build');
  assert.match(text, /\{ tasks, testCmd, risk: \[axes\], repoRoot, request, done\?: \[ids\], doneFiles\?: \[paths\], baseline\?: false \}/);
  assert.match(text, /`stop` questions go to the owner in one AskUserQuestion round/);
});

test('given deliver SKILL.md, when read, then real tests run only after one question proposing the exact command', () => {
  // Given
  const text = skill();

  // When
  const hit = text.match(/\*\*Real tests\*\*[^]*?only after one AskUserQuestion that\s+proposes the exact command/);

  // Then
  assert.ok(hit, 'real tests are not gated by a question');
  assert.match(text, /`run` skill/);
});

test('given deliver SKILL.md, when read, then the verdict carries the Verification table', () => {
  // Given
  const text = skill();

  // When
  const verdict = text.split('\n### 6. The verdict')[1];

  // Then
  assert.match(verdict, /`Verification` table/);
  assert.match(verdict, /Level \| Command \| Deciding line \| Status/);
});

test('given deliver SKILL.md, when checked against the retired loop, then no stale name remains and the caps hold', () => {
  // Given
  const text = skill();

  // When
  const stale = text.match(/dev-loop|perimeter|gate\.mjs|STALL|scope-guard/g);

  // Then
  assert.equal(stale, null);
  assert.ok(text.split('\n').length <= 120);
  assert.ok(Buffer.byteLength(text) <= 7000);
});

test('given the kit, when node tools/validate.mjs runs, then it is clean', () => {
  // Given
  const script = join(ROOT, 'tools', 'validate.mjs');

  // When
  const res = spawnSync(process.execPath, [script], { encoding: 'utf8', cwd: ROOT });

  // Then
  assert.equal(res.status, 0, res.stdout + res.stderr);
  assert.ok(!/ERROR/.test(res.stdout), res.stdout);
});

test('given CLAUDE.md rule 1, when read, then it says deliver\'s own gates (owner ok at M/L) still apply', () => {
  // Given
  const text = read('CLAUDE.md');

  // When
  const rule = text.split('\n').slice(text.split('\n').findIndex((l) => l.startsWith('1. '))).join('\n').split(/\n(?=\d\. )/)[0];

  // Then
  assert.match(rule, /deliver/);
  assert.match(rule, /owner ok/);
  assert.match(rule, /M\/L/);
});
